-- =====================================================================
-- SQL Practice Workbook -- MySQL 8.0+ CSV loader
-- Fictional company: Lumen Analytics (SaaS data platform + AI features)
--
-- Run:  mysql -e "CREATE DATABASE sql_workbook CHARACTER SET utf8mb4" && mysql --local-infile=1 sql_workbook < load_csv_mysql.sql   (server: local_infile=ON)
--
-- Generated by scripts/build_setup.py from scripts/schema.py and data/*.csv.
-- Do not edit by hand: change the generator and rebuild instead.
-- Re-running this script drops and recreates all workbook tables.
-- All timestamps are UTC without time zone. "Today" for the workbook is
-- 2025-07-01 (the data ends at 2025-06-30 23:59:59).
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS pipeline_runs;
DROP TABLE IF EXISTS retrieval_evaluations;
DROP TABLE IF EXISTS eval_queries;
DROP TABLE IF EXISTS ai_feedback;
DROP TABLE IF EXISTS llm_request_chunks;
DROP TABLE IF EXISTS llm_requests;
DROP TABLE IF EXISTS retrieval_configs;
DROP TABLE IF EXISTS prompts;
DROP TABLE IF EXISTS llm_pricing;
DROP TABLE IF EXISTS llm_models;
DROP TABLE IF EXISTS document_chunks;
DROP TABLE IF EXISTS documents;
DROP TABLE IF EXISTS model_evaluations;
DROP TABLE IF EXISTS model_predictions;
DROP TABLE IF EXISTS model_versions;
DROP TABLE IF EXISTS training_labels;
DROP TABLE IF EXISTS entity_features;
DROP TABLE IF EXISTS ml_entities;
DROP TABLE IF EXISTS experiment_assignments;
DROP TABLE IF EXISTS experiments;
DROP TABLE IF EXISTS events;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS support_tickets;
DROP TABLE IF EXISTS payments;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS product_categories;
DROP TABLE IF EXISTS subscriptions;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS organizations;
DROP TABLE IF EXISTS plans;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------- tables
-- plans: One row per subscription plan.
CREATE TABLE plans (
  plan_id INT NOT NULL,
  plan_name VARCHAR(30) NOT NULL,
  tier_rank SMALLINT NOT NULL,
  price_per_seat_month DECIMAL(10,2) NOT NULL,
  annual_discount_pct DECIMAL(5,2),
  seat_limit INT,
  is_active BOOLEAN NOT NULL,
  launched_on DATE NOT NULL,
  CONSTRAINT pk_plans PRIMARY KEY (plan_id),
  CONSTRAINT uq_plans_1 UNIQUE (plan_name),
  CONSTRAINT ck_plans_1 CHECK (price_per_seat_month >= 0),
  CONSTRAINT ck_plans_2 CHECK (tier_rank BETWEEN 0 AND 4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- organizations: One row per customer organization (account).
CREATE TABLE organizations (
  org_id INT NOT NULL,
  org_name VARCHAR(120) NOT NULL,
  parent_org_id INT,
  industry VARCHAR(40),
  segment VARCHAR(20) NOT NULL,
  employee_band VARCHAR(20),
  country_code CHAR(2) NOT NULL,
  timezone VARCHAR(40) NOT NULL,
  created_at DATETIME NOT NULL,
  is_deleted BOOLEAN NOT NULL,
  deleted_at DATETIME,
  CONSTRAINT pk_organizations PRIMARY KEY (org_id),
  CONSTRAINT ck_organizations_1 CHECK (segment IN ('SMB','Mid-Market','Enterprise')),
  CONSTRAINT ck_organizations_2 CHECK (deleted_at IS NULL OR is_deleted = TRUE),
  CONSTRAINT fk_organizations_1 FOREIGN KEY (parent_org_id) REFERENCES organizations (org_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- users: One row per user account (login). A real person may have more than one account.
CREATE TABLE users (
  user_id INT NOT NULL,
  org_id INT NOT NULL,
  email VARCHAR(255) NOT NULL,
  full_name VARCHAR(120) NOT NULL,
  role VARCHAR(20) NOT NULL,
  signup_at DATETIME NOT NULL,
  last_login_at DATETIME,
  status VARCHAR(20) NOT NULL,
  acquisition_channel VARCHAR(30),
  country_code CHAR(2),
  referred_by_user_id INT,
  marketing_opt_in BOOLEAN,
  CONSTRAINT pk_users PRIMARY KEY (user_id),
  CONSTRAINT ck_users_1 CHECK (role IN ('admin','member','viewer')),
  CONSTRAINT ck_users_2 CHECK (status IN ('active','inactive','deleted')),
  CONSTRAINT fk_users_1 FOREIGN KEY (org_id) REFERENCES organizations (org_id),
  CONSTRAINT fk_users_2 FOREIGN KEY (referred_by_user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- subscriptions: One row per subscription period of an organization on one plan.
CREATE TABLE subscriptions (
  subscription_id INT NOT NULL,
  org_id INT NOT NULL,
  plan_id INT NOT NULL,
  status VARCHAR(20) NOT NULL,
  billing_cycle VARCHAR(10) NOT NULL,
  seats INT NOT NULL,
  mrr DECIMAL(10,2) NOT NULL,
  started_at DATETIME NOT NULL,
  ended_at DATETIME,
  cancel_reason VARCHAR(50),
  CONSTRAINT pk_subscriptions PRIMARY KEY (subscription_id),
  CONSTRAINT ck_subscriptions_1 CHECK (seats > 0),
  CONSTRAINT ck_subscriptions_2 CHECK (mrr >= 0),
  CONSTRAINT ck_subscriptions_3 CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT ck_subscriptions_4 CHECK (status IN ('trialing','active','past_due','canceled','switched')),
  CONSTRAINT ck_subscriptions_5 CHECK (billing_cycle IN ('monthly','annual')),
  CONSTRAINT fk_subscriptions_1 FOREIGN KEY (org_id) REFERENCES organizations (org_id),
  CONSTRAINT fk_subscriptions_2 FOREIGN KEY (plan_id) REFERENCES plans (plan_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- product_categories: One row per product category node.
CREATE TABLE product_categories (
  category_id INT NOT NULL,
  category_name VARCHAR(60) NOT NULL,
  parent_category_id INT,
  CONSTRAINT pk_product_categories PRIMARY KEY (category_id),
  CONSTRAINT uq_product_categories_1 UNIQUE (category_name),
  CONSTRAINT fk_product_categories_1 FOREIGN KEY (parent_category_id) REFERENCES product_categories (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- products: One row per sellable product (add-ons, credit packs, services).
CREATE TABLE products (
  product_id INT NOT NULL,
  product_name VARCHAR(80) NOT NULL,
  category_id INT NOT NULL,
  list_price DECIMAL(10,2) NOT NULL,
  is_active BOOLEAN NOT NULL,
  launched_on DATE NOT NULL,
  CONSTRAINT pk_products PRIMARY KEY (product_id),
  CONSTRAINT uq_products_1 UNIQUE (product_name),
  CONSTRAINT ck_products_1 CHECK (list_price >= 0),
  CONSTRAINT fk_products_1 FOREIGN KEY (category_id) REFERENCES product_categories (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- orders: One row per order (checkout).
CREATE TABLE orders (
  order_id INT NOT NULL,
  user_id INT NOT NULL,
  org_id INT NOT NULL,
  order_ts DATETIME NOT NULL,
  status VARCHAR(20) NOT NULL,
  sales_channel VARCHAR(20) NOT NULL,
  discount_code VARCHAR(20),
  order_total DECIMAL(12,2) NOT NULL,
  CONSTRAINT pk_orders PRIMARY KEY (order_id),
  CONSTRAINT ck_orders_1 CHECK (order_total >= 0),
  CONSTRAINT ck_orders_2 CHECK (status IN ('completed','pending','canceled','refunded')),
  CONSTRAINT fk_orders_1 FOREIGN KEY (user_id) REFERENCES users (user_id),
  CONSTRAINT fk_orders_2 FOREIGN KEY (org_id) REFERENCES organizations (org_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- order_items: One row per order line.
CREATE TABLE order_items (
  order_id INT NOT NULL,
  line_number SMALLINT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL,
  discount_amount DECIMAL(10,2) NOT NULL,
  CONSTRAINT pk_order_items PRIMARY KEY (order_id, line_number),
  CONSTRAINT ck_order_items_1 CHECK (quantity > 0),
  CONSTRAINT ck_order_items_2 CHECK (unit_price >= 0),
  CONSTRAINT ck_order_items_3 CHECK (discount_amount >= 0),
  CONSTRAINT fk_order_items_1 FOREIGN KEY (order_id) REFERENCES orders (order_id),
  CONSTRAINT fk_order_items_2 FOREIGN KEY (product_id) REFERENCES products (product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- payments: One row per payment attempt.
CREATE TABLE payments (
  payment_id INT NOT NULL,
  order_id INT NOT NULL,
  attempted_at DATETIME NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  method VARCHAR(20) NOT NULL,
  status VARCHAR(20) NOT NULL,
  failure_reason VARCHAR(40),
  refunded_amount DECIMAL(12,2),
  refunded_at DATETIME,
  CONSTRAINT pk_payments PRIMARY KEY (payment_id),
  CONSTRAINT ck_payments_1 CHECK (amount >= 0),
  CONSTRAINT ck_payments_2 CHECK (status IN ('succeeded','failed','pending','refunded')),
  CONSTRAINT fk_payments_1 FOREIGN KEY (order_id) REFERENCES orders (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- support_tickets: One row per support ticket.
CREATE TABLE support_tickets (
  ticket_id INT NOT NULL,
  org_id INT NOT NULL,
  user_id INT,
  created_at DATETIME NOT NULL,
  first_response_at DATETIME,
  resolved_at DATETIME,
  priority VARCHAR(10) NOT NULL,
  category VARCHAR(30) NOT NULL,
  status VARCHAR(20) NOT NULL,
  channel VARCHAR(20) NOT NULL,
  csat_score SMALLINT,
  CONSTRAINT pk_support_tickets PRIMARY KEY (ticket_id),
  CONSTRAINT ck_support_tickets_1 CHECK (csat_score IS NULL OR csat_score BETWEEN 1 AND 5),
  CONSTRAINT fk_support_tickets_1 FOREIGN KEY (org_id) REFERENCES organizations (org_id),
  CONSTRAINT fk_support_tickets_2 FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- sessions: One row per application session.
CREATE TABLE sessions (
  session_id INT NOT NULL,
  user_id INT NOT NULL,
  started_at DATETIME NOT NULL,
  ended_at DATETIME,
  device_type VARCHAR(10) NOT NULL,
  app_version VARCHAR(10),
  CONSTRAINT pk_sessions PRIMARY KEY (session_id),
  CONSTRAINT ck_sessions_1 CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT fk_sessions_1 FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- events: One row per tracked product event.
CREATE TABLE events (
  event_id BIGINT NOT NULL,
  user_id INT NOT NULL,
  session_id INT,
  event_ts DATETIME NOT NULL,
  event_name VARCHAR(40) NOT NULL,
  properties JSON,
  CONSTRAINT pk_events PRIMARY KEY (event_id),
  CONSTRAINT fk_events_1 FOREIGN KEY (user_id) REFERENCES users (user_id),
  CONSTRAINT fk_events_2 FOREIGN KEY (session_id) REFERENCES sessions (session_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- experiments: One row per A/B experiment.
CREATE TABLE experiments (
  experiment_id INT NOT NULL,
  experiment_name VARCHAR(60) NOT NULL,
  hypothesis VARCHAR(255) NOT NULL,
  primary_metric VARCHAR(60) NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE,
  status VARCHAR(20) NOT NULL,
  CONSTRAINT pk_experiments PRIMARY KEY (experiment_id),
  CONSTRAINT uq_experiments_1 UNIQUE (experiment_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- experiment_assignments: One row per (experiment, user).
CREATE TABLE experiment_assignments (
  experiment_id INT NOT NULL,
  user_id INT NOT NULL,
  variant VARCHAR(20) NOT NULL,
  assigned_at DATETIME NOT NULL,
  CONSTRAINT pk_experiment_assignments PRIMARY KEY (experiment_id, user_id),
  CONSTRAINT fk_experiment_assignments_1 FOREIGN KEY (experiment_id) REFERENCES experiments (experiment_id),
  CONSTRAINT fk_experiment_assignments_2 FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ml_entities: One row per entity scored by the ML platform (here: a user).
CREATE TABLE ml_entities (
  entity_id INT NOT NULL,
  user_id INT NOT NULL,
  org_id INT NOT NULL,
  registered_at DATETIME NOT NULL,
  is_test_account BOOLEAN NOT NULL,
  CONSTRAINT pk_ml_entities PRIMARY KEY (entity_id),
  CONSTRAINT uq_ml_entities_1 UNIQUE (user_id),
  CONSTRAINT fk_ml_entities_1 FOREIGN KEY (user_id) REFERENCES users (user_id),
  CONSTRAINT fk_ml_entities_2 FOREIGN KEY (org_id) REFERENCES organizations (org_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- entity_features: One row per (entity, feature snapshot time).
CREATE TABLE entity_features (
  entity_id INT NOT NULL,
  as_of_ts DATETIME NOT NULL,
  sessions_7d INT,
  sessions_28d INT,
  events_28d INT,
  days_since_last_session INT,
  open_tickets INT,
  avg_session_minutes DOUBLE PRECISION,
  seats_used_pct DOUBLE PRECISION,
  feature_source VARCHAR(20) NOT NULL,
  ingested_at DATETIME NOT NULL,
  CONSTRAINT pk_entity_features PRIMARY KEY (entity_id, as_of_ts),
  CONSTRAINT ck_entity_features_1 CHECK (ingested_at >= as_of_ts),
  CONSTRAINT fk_entity_features_1 FOREIGN KEY (entity_id) REFERENCES ml_entities (entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- training_labels: One row per (entity, observation date, label) -- but see duplicates below.
CREATE TABLE training_labels (
  label_id INT NOT NULL,
  entity_id INT NOT NULL,
  label_name VARCHAR(30) NOT NULL,
  observation_date DATE NOT NULL,
  label_value SMALLINT,
  label_available_at DATETIME,
  CONSTRAINT pk_training_labels PRIMARY KEY (label_id),
  CONSTRAINT ck_training_labels_1 CHECK (label_value IS NULL OR label_value IN (0, 1)),
  CONSTRAINT fk_training_labels_1 FOREIGN KEY (entity_id) REFERENCES ml_entities (entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- model_versions: One row per trained model version.
CREATE TABLE model_versions (
  model_version_id INT NOT NULL,
  model_name VARCHAR(40) NOT NULL,
  version_label VARCHAR(10) NOT NULL,
  parent_version_id INT,
  algorithm VARCHAR(40) NOT NULL,
  training_data_end DATE NOT NULL,
  trained_at DATETIME NOT NULL,
  deployed_at DATETIME,
  retired_at DATETIME,
  stage VARCHAR(20) NOT NULL,
  default_threshold DECIMAL(4,3) NOT NULL,
  hyperparameters JSON,
  CONSTRAINT pk_model_versions PRIMARY KEY (model_version_id),
  CONSTRAINT uq_model_versions_1 UNIQUE (model_name, version_label),
  CONSTRAINT ck_model_versions_1 CHECK (default_threshold BETWEEN 0 AND 1),
  CONSTRAINT fk_model_versions_1 FOREIGN KEY (parent_version_id) REFERENCES model_versions (model_version_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- model_predictions: One row per prediction (model version, entity, scoring run).
CREATE TABLE model_predictions (
  prediction_id BIGINT NOT NULL,
  model_version_id INT NOT NULL,
  entity_id INT NOT NULL,
  batch_id VARCHAR(30) NOT NULL,
  predicted_at DATETIME NOT NULL,
  score DOUBLE PRECISION,
  threshold DECIMAL(4,3) NOT NULL,
  predicted_label SMALLINT,
  feature_as_of_ts DATETIME,
  CONSTRAINT pk_model_predictions PRIMARY KEY (prediction_id),
  CONSTRAINT ck_model_predictions_1 CHECK (score IS NULL OR (score >= 0 AND score <= 1)),
  CONSTRAINT ck_model_predictions_2 CHECK (predicted_label IS NULL OR predicted_label IN (0, 1)),
  CONSTRAINT fk_model_predictions_1 FOREIGN KEY (model_version_id) REFERENCES model_versions (model_version_id),
  CONSTRAINT fk_model_predictions_2 FOREIGN KEY (entity_id) REFERENCES ml_entities (entity_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- model_evaluations: One row per (model version, split, metric).
CREATE TABLE model_evaluations (
  evaluation_id INT NOT NULL,
  model_version_id INT NOT NULL,
  eval_split VARCHAR(12) NOT NULL,
  metric_name VARCHAR(20) NOT NULL,
  metric_value DOUBLE PRECISION NOT NULL,
  evaluated_at DATETIME NOT NULL,
  CONSTRAINT pk_model_evaluations PRIMARY KEY (evaluation_id),
  CONSTRAINT uq_model_evaluations_1 UNIQUE (model_version_id, eval_split, metric_name),
  CONSTRAINT fk_model_evaluations_1 FOREIGN KEY (model_version_id) REFERENCES model_versions (model_version_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- documents: One row per document VERSION.
CREATE TABLE documents (
  document_id INT NOT NULL,
  doc_key VARCHAR(100) NOT NULL,
  version_number INT NOT NULL,
  title VARCHAR(200) NOT NULL,
  source_type VARCHAR(20) NOT NULL,
  status VARCHAR(20) NOT NULL,
  language VARCHAR(5),
  access_level VARCHAR(20) NOT NULL,
  word_count INT NOT NULL,
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL,
  last_indexed_at DATETIME,
  is_deleted BOOLEAN NOT NULL,
  metadata JSON,
  CONSTRAINT pk_documents PRIMARY KEY (document_id),
  CONSTRAINT uq_documents_1 UNIQUE (doc_key, version_number),
  CONSTRAINT ck_documents_1 CHECK (status IN ('draft','published','archived')),
  CONSTRAINT ck_documents_2 CHECK (version_number >= 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- document_chunks: One row per chunk of a document version.
CREATE TABLE document_chunks (
  chunk_id INT NOT NULL,
  document_id INT NOT NULL,
  chunk_index INT NOT NULL,
  chunk_text TEXT NOT NULL,
  token_count INT NOT NULL,
  content_hash VARCHAR(64) NOT NULL,
  embedding_model VARCHAR(40),
  embedded_at DATETIME,
  CONSTRAINT pk_document_chunks PRIMARY KEY (chunk_id),
  CONSTRAINT uq_document_chunks_1 UNIQUE (document_id, chunk_index),
  CONSTRAINT ck_document_chunks_1 CHECK (token_count > 0),
  CONSTRAINT fk_document_chunks_1 FOREIGN KEY (document_id) REFERENCES documents (document_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- llm_models: One row per LLM the application can call.
CREATE TABLE llm_models (
  model_name VARCHAR(40) NOT NULL,
  provider VARCHAR(40) NOT NULL,
  context_window INT NOT NULL,
  is_self_hosted BOOLEAN NOT NULL,
  released_on DATE NOT NULL,
  CONSTRAINT pk_llm_models PRIMARY KEY (model_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- llm_pricing: One row per (model, price period).
CREATE TABLE llm_pricing (
  model_name VARCHAR(40) NOT NULL,
  effective_from DATE NOT NULL,
  effective_to DATE,
  input_usd_per_1k DECIMAL(10,5) NOT NULL,
  output_usd_per_1k DECIMAL(10,5) NOT NULL,
  CONSTRAINT pk_llm_pricing PRIMARY KEY (model_name, effective_from),
  CONSTRAINT ck_llm_pricing_1 CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT fk_llm_pricing_1 FOREIGN KEY (model_name) REFERENCES llm_models (model_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- prompts: One row per prompt template version.
CREATE TABLE prompts (
  prompt_version_id INT NOT NULL,
  prompt_name VARCHAR(40) NOT NULL,
  version INT NOT NULL,
  template_text TEXT NOT NULL,
  created_at DATETIME NOT NULL,
  author VARCHAR(60) NOT NULL,
  is_active BOOLEAN NOT NULL,
  CONSTRAINT pk_prompts PRIMARY KEY (prompt_version_id),
  CONSTRAINT uq_prompts_1 UNIQUE (prompt_name, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- retrieval_configs: One row per retrieval pipeline configuration.
CREATE TABLE retrieval_configs (
  config_id INT NOT NULL,
  config_name VARCHAR(40) NOT NULL,
  embedding_model VARCHAR(40) NOT NULL,
  chunk_size_tokens INT NOT NULL,
  chunk_overlap_tokens INT NOT NULL,
  top_k INT NOT NULL,
  uses_reranker BOOLEAN NOT NULL,
  created_at DATETIME NOT NULL,
  CONSTRAINT pk_retrieval_configs PRIMARY KEY (config_id),
  CONSTRAINT uq_retrieval_configs_1 UNIQUE (config_name),
  CONSTRAINT ck_retrieval_configs_1 CHECK (top_k > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- llm_requests: One row per LLM API call made by the application.
CREATE TABLE llm_requests (
  request_id BIGINT NOT NULL,
  trace_id VARCHAR(36),
  org_id INT NOT NULL,
  user_id INT,
  feature VARCHAR(20) NOT NULL,
  model_name VARCHAR(40) NOT NULL,
  prompt_version_id INT,
  retrieval_config_id INT,
  requested_at DATETIME NOT NULL,
  status VARCHAR(20) NOT NULL,
  error_code VARCHAR(30),
  latency_ms INT,
  input_tokens INT NOT NULL,
  output_tokens INT,
  cache_hit BOOLEAN NOT NULL,
  request_metadata JSON,
  CONSTRAINT pk_llm_requests PRIMARY KEY (request_id),
  CONSTRAINT ck_llm_requests_1 CHECK (input_tokens > 0),
  CONSTRAINT ck_llm_requests_2 CHECK (output_tokens IS NULL OR output_tokens >= 0),
  CONSTRAINT ck_llm_requests_3 CHECK (status IN ('success','error','timeout','rate_limited','content_filtered')),
  CONSTRAINT fk_llm_requests_1 FOREIGN KEY (org_id) REFERENCES organizations (org_id),
  CONSTRAINT fk_llm_requests_2 FOREIGN KEY (user_id) REFERENCES users (user_id),
  CONSTRAINT fk_llm_requests_3 FOREIGN KEY (model_name) REFERENCES llm_models (model_name),
  CONSTRAINT fk_llm_requests_4 FOREIGN KEY (prompt_version_id) REFERENCES prompts (prompt_version_id),
  CONSTRAINT fk_llm_requests_5 FOREIGN KEY (retrieval_config_id) REFERENCES retrieval_configs (config_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- llm_request_chunks: One row per (request, retrieved chunk rank).
CREATE TABLE llm_request_chunks (
  request_id BIGINT NOT NULL,
  rank_position SMALLINT NOT NULL,
  chunk_id INT NOT NULL,
  similarity DOUBLE PRECISION NOT NULL,
  CONSTRAINT pk_llm_request_chunks PRIMARY KEY (request_id, rank_position),
  CONSTRAINT ck_llm_request_chunks_1 CHECK (rank_position >= 1),
  CONSTRAINT fk_llm_request_chunks_1 FOREIGN KEY (request_id) REFERENCES llm_requests (request_id),
  CONSTRAINT fk_llm_request_chunks_2 FOREIGN KEY (chunk_id) REFERENCES document_chunks (chunk_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ai_feedback: One row per feedback click. A user can change their mind, producing several rows per request.
CREATE TABLE ai_feedback (
  feedback_id INT NOT NULL,
  request_id BIGINT NOT NULL,
  user_id INT,
  feedback_type VARCHAR(20) NOT NULL,
  reason_tag VARCHAR(30),
  comment_text VARCHAR(500),
  created_at DATETIME NOT NULL,
  CONSTRAINT pk_ai_feedback PRIMARY KEY (feedback_id),
  CONSTRAINT fk_ai_feedback_1 FOREIGN KEY (request_id) REFERENCES llm_requests (request_id),
  CONSTRAINT fk_ai_feedback_2 FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- eval_queries: One row per offline retrieval-evaluation query.
CREATE TABLE eval_queries (
  query_id INT NOT NULL,
  query_text VARCHAR(300) NOT NULL,
  gold_doc_key VARCHAR(100) NOT NULL,
  query_type VARCHAR(20) NOT NULL,
  created_at DATETIME NOT NULL,
  CONSTRAINT pk_eval_queries PRIMARY KEY (query_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- retrieval_evaluations: One row per (config, query, rank).
CREATE TABLE retrieval_evaluations (
  config_id INT NOT NULL,
  query_id INT NOT NULL,
  rank_position SMALLINT NOT NULL,
  chunk_id INT NOT NULL,
  similarity DOUBLE PRECISION NOT NULL,
  is_relevant BOOLEAN,
  evaluated_at DATETIME NOT NULL,
  CONSTRAINT pk_retrieval_evaluations PRIMARY KEY (config_id, query_id, rank_position),
  CONSTRAINT ck_retrieval_evaluations_1 CHECK (rank_position >= 1),
  CONSTRAINT fk_retrieval_evaluations_1 FOREIGN KEY (config_id) REFERENCES retrieval_configs (config_id),
  CONSTRAINT fk_retrieval_evaluations_2 FOREIGN KEY (query_id) REFERENCES eval_queries (query_id),
  CONSTRAINT fk_retrieval_evaluations_3 FOREIGN KEY (chunk_id) REFERENCES document_chunks (chunk_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- pipeline_runs: One row per pipeline execution attempt.
CREATE TABLE pipeline_runs (
  run_id INT NOT NULL,
  pipeline_name VARCHAR(40) NOT NULL,
  run_date DATE NOT NULL,
  attempt SMALLINT NOT NULL,
  started_at DATETIME NOT NULL,
  finished_at DATETIME,
  status VARCHAR(20) NOT NULL,
  rows_processed INT,
